<?php
declare(strict_types=1);
function e(mixed $v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function redirect(string $url): never { header('Location: '.$url); exit; }
function flash(string $type,string $message): void { $_SESSION['_flash']=[$type,$message]; }
function get_flash(): ?array { $f=$_SESSION['_flash']??null; unset($_SESSION['_flash']); return $f; }
function csrf_token(): string { if(empty($_SESSION['_csrf'])) $_SESSION['_csrf']=bin2hex(random_bytes(32)); return $_SESSION['_csrf']; }
function verify_csrf(): void { if(!hash_equals($_SESSION['_csrf']??'',$_POST['_csrf']??'')){ http_response_code(419); exit('Token de segurança inválido.'); } }
function post(string $key,string $default=''): string { return trim((string)($_POST[$key]??$default)); }
function current_user(): ?array { return $_SESSION['user']??null; }
function require_login(): void {
    if(!current_user()) redirect('index.php?page=login');
    // Revalida no banco: suspensão, troca de perfil/nome/e-mail e plano valem imediatamente.
    $q=db()->prepare('SELECT u.name,u.email,u.avatar,u.job_title,u.phone,u.role,u.status,u.deleted,c.status company_status,s.plan_code FROM users u JOIN companies c ON c.id=u.company_id LEFT JOIN company_subscriptions s ON s.company_id=c.id AND s.status="active" WHERE u.id=? LIMIT 1');
    $q->execute([$_SESSION['user']['id']]); $fresh=$q->fetch();
    if(!$fresh || (int)$fresh['deleted']===1){ Auth::logout(); redirect('index.php?page=login'); }
    if($fresh['status']!=='active'){ $n=(string)($_SESSION['user']['name']??''); Auth::logout(); suspended_page('user',$n); }
    $_SESSION['user']=array_merge($_SESSION['user'],$fresh);
    if(($fresh['company_status']??'active')==='suspended') suspended_page('company',(string)($_SESSION['user']['name']??''));
}
function favicon_tags(): string { return '<link rel="icon" href="favicon.ico" sizes="any"><link rel="icon" type="image/png" sizes="32x32" href="assets/favicon-32.png"><link rel="icon" type="image/png" sizes="192x192" href="assets/icon-192.png"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png"><meta name="theme-color" content="#0b1020">'; }
function suspended_page(string $kind,string $name=''): never {
    http_response_code(403);
    $company=$kind==='company';
    $title=$company?'Conta suspensa':'Acesso suspenso';
    $text=$company?'O acesso da sua empresa ao Inova CRM está temporariamente suspenso. Seus dados continuam guardados e seguros.':'O seu acesso ao Inova CRM está temporariamente suspenso. Seus dados continuam guardados e seguros.';
    ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title><?=e($title)?> · Inova CRM</title><?=favicon_tags()?><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><main class="suspended-card"><div class="suspended-icon"><svg viewBox="0 0 24 24" width="38" height="38" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="10.5" width="16" height="10" rx="2.5"/><path d="M8 10.5V7.5a4 4 0 0 1 8 0v3"/><circle cx="12" cy="15.5" r="1.2" fill="currentColor"/></svg></div><span class="eyebrow">ACESSO PAUSADO</span><h1><?=e($title)?></h1><?php if($name!==''): ?><p class="suspended-hi">Olá, <strong><?=e($name)?></strong>.</p><?php endif; ?><p><?=e($text)?></p><div class="suspended-steps"><div><b>1</b><span>Fale com o responsável pela conta ou com o suporte do Inova CRM.</span></div><div><b>2</b><span>Regularize a pendência informada, se houver.</span></div><div><b>3</b><span>Assim que for reativada, é só entrar novamente.</span></div></div><a class="btn primary" href="index.php?page=<?=$company?'logout':'login'?>"><?=$company?'Sair da conta':'Voltar ao login'?></a><p class="hint">Conecte. Organize. <strong>Cresça.</strong></p></main></body></html><?php exit;
}
function require_admin(): void { require_login(); if((current_user()['role']??'')!=='global_admin'){ http_response_code(403); exit('Acesso negado.'); } }
function is_global_admin(): bool { return (current_user()['role']??'')==='global_admin'; }
// Exclusão é exclusiva do administrador geral: valida perfil (403) e CSRF no servidor.
function require_admin_delete(): void { if(!is_global_admin()){ http_response_code(403); exit('Acesso negado.'); } verify_csrf(); }
function delete_button(string $page,string $action,string $field,int $id,string $confirm): void { ?><form method="post" action="index.php?page=<?=e($page)?>" style="display:inline" onsubmit="return confirm(<?=e(json_encode($confirm,JSON_UNESCAPED_UNICODE))?>);"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="<?=e($action)?>"><input type="hidden" name="<?=e($field)?>" value="<?=$id?>"><button class="btn small danger">Excluir</button></form><?php }
function tenant_id(): int { return (int)(current_user()['company_id']??0); }
function is_super_admin(): bool { $u=current_user(); return ($u['role']??'')==='global_admin' || ($u['plan_code']??'')==='admin'; }
function plan_limits(): array {
    // Perfil "Administrador geral": sem limites, independente de qualquer plano comercial.
    if(is_super_admin()){ $m=PHP_INT_MAX; return ['customers'=>$m,'deals'=>$m,'users'=>$m,'tasks'=>$m]; }
    $p=current_user()['plan_code']??'free';
    return ['free'=>['customers'=>5,'deals'=>5,'users'=>1,'tasks'=>5], 'pro'=>['customers'=>100,'deals'=>100,'users'=>3,'tasks'=>100], 'premium'=>['customers'=>500,'deals'=>500,'users'=>5,'tasks'=>500]][$p]??['customers'=>5,'deals'=>5,'users'=>1,'tasks'=>5];
}
function plan_limit_text(string $k): string { $v=plan_limits()[$k]??0; return $v>=PHP_INT_MAX ? 'ilimitado (Administrador geral)' : 'de '.$v.' no plano'; }
function count_tenant(string $table,string $where='1=1',array $params=[]): int { $allowed=['customers','deals','tasks','users']; if(!in_array($table,$allowed,true)) return 0; if($table==='users') $where.=' AND deleted=0'; $q=db()->prepare("SELECT COUNT(*) FROM `$table` WHERE company_id=? AND ($where)"); $q->execute(array_merge([tenant_id()],$params)); return (int)$q->fetchColumn(); }
function limit_reached(string $type,string $where='1=1',array $params=[]): bool { $l=plan_limits(); return count_tenant($type,$where,$params)>=$l[$type]; }
function audit(string $action,string $entity='',?int $entityId=null,string $details=''): void { $q=db()->prepare('INSERT INTO admin_audit_logs(user_id,company_id,action,entity,entity_id,details,created_at) VALUES(?,?,?,?,?,?,NOW())'); $u=current_user(); $q->execute([$u['id']??null,$u['company_id']??null,$action,$entity,$entityId,$details]); }
function layout_start(string $title): void { global $config; $u=current_user(); $flash=get_flash(); ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · Inova CRM</title><?=favicon_tags()?><link rel="stylesheet" href="assets/app.css"></head><body><div class="app-shell"><div class="sidebar-backdrop" data-nav-close></div><aside class="sidebar" id="sidebar" aria-label="Menu principal"><button type="button" class="nav-close" data-nav-close aria-label="Fechar menu">&times;</button><a class="brand" href="index.php" aria-label="Inova CRM - início"><img class="brand-mark" src="assets/brand-mark.png" alt="" width="46" height="46"><span class="brand-text"><strong>Inova</strong><em>CRM</em></span></a><nav><?php $cur=$_GET['page']??'dashboard'; $items=['dashboard'=>['index.php','⌂ Dashboard'],'customers'=>['index.php?page=customers','♙ Clientes'],'deals'=>['index.php?page=deals','◈ Oportunidades'],'tasks'=>['index.php?page=tasks','✓ Tarefas']]; if($u && in_array($u['role'],['owner','global_admin'],true)) $items['users']=['index.php?page=users','☻ Usuários']; if($u && $u['role']==='global_admin') $items['admin']=['index.php?page=admin','⚙ Administração']; foreach($items as $k=>$it): ?><a href="<?=$it[0]?>" class="<?=$cur===$k?'active':''?>"><?=$it[1]?></a><?php endforeach; ?><a href="index.php?page=logout">↪ Sair</a></nav><div class="side-foot">Conecte. Organize.<br><strong>Cresça.</strong></div></aside><main class="main"><header class="topbar"><button type="button" class="menu-btn" id="menu-btn" aria-label="Abrir menu" aria-controls="sidebar" aria-expanded="false"><span></span><span></span><span></span></button><div class="topbar-title"><span class="eyebrow">INOVA CRM</span><h1><?=e($title)?></h1></div><?php if($u): $rl=['global_admin'=>'Administrador geral','owner'=>'Responsável','member'=>'Membro'][$u['role']??'']??($u['role']??''); ?><div class="profile-menu"><button type="button" class="user-pill" id="profile-btn" aria-haspopup="true" aria-expanded="false" aria-controls="profile-dd"><?=avatar_html($u,'avatar-sm')?><span class="user-info"><b><?=e($u['name'])?></b><small><?=e(($u['job_title']??'')?:$rl)?></small></span><svg class="chev" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><div class="profile-dd" id="profile-dd" hidden><div class="dd-head"><?=avatar_html($u,'avatar-md')?><div><strong><?=e($u['name'])?></strong><small><?=e($u['email']??'')?></small><span class="badge pro"><?=e($rl)?></span></div></div><a href="index.php?page=profile">Meu perfil</a><a href="index.php?page=logout" class="dd-out">Sair</a></div></div><?php endif; ?></header><?php if($flash): ?><div class="flash <?=$flash[0]?>"><?=e($flash[1])?></div><?php endif; ?><?php }
function layout_end(): void { ?></main></div><script>(function(){var b=document.body,m=document.getElementById('menu-btn');function set(o){b.classList.toggle('nav-open',o);if(m){m.setAttribute('aria-expanded',o?'true':'false');}}if(m)m.addEventListener('click',function(){set(!b.classList.contains('nav-open'));});var pb=document.getElementById('profile-btn'),pd=document.getElementById('profile-dd');function pset(o){if(!pb)return;pd.hidden=!o;pb.setAttribute('aria-expanded',o?'true':'false');}if(pb){pb.addEventListener('click',function(e){e.stopPropagation();pset(pd.hidden);});document.addEventListener('click',function(e){if(!pd.hidden&&!pd.contains(e.target))pset(false);});}document.querySelectorAll('[data-nav-close],.sidebar nav a').forEach(function(el){el.addEventListener('click',function(){set(false);});});document.addEventListener('keydown',function(e){if(e.key==='Escape'){set(false);pset(false);}});window.addEventListener('resize',function(){if(window.innerWidth>900)set(false);});})();</script></body></html><?php }
